import { Stats } from "@/registry/bases/base/blocks/stats-02/components/stats-02"
import { dictionary } from "@/registry/bases/base/blocks/stats-02/stats-02-dictionary"

export default async function Page({
  params,
}: {
  params?: Promise<{ lang?: string }>
}) {
  const { lang } = (await params) ?? {}
  const locale = lang === "ar" ? "ar" : "en"
  return <Stats dictionary={dictionary[locale]} lang={locale} />
}

import { cn } from "@/lib/utils"

export type StatsDictionary = {
  title: string
  description: string
  items: {
    value: string
    label: string
  }[]
}

export function Stats({
  dictionary,
  lang,
  className,
}: {
  dictionary: StatsDictionary
  lang: "en" | "ar"
  className?: string
}) {
  const dir = lang === "ar" ? "rtl" : "ltr"

  return (
    <section
      dir={dir}
      aria-labelledby="stats-02-title"
      className={cn("bg-background py-16 md:py-24", className)}
    >
      <div className="mx-auto max-w-6xl px-6 lg:px-8">
        <div className="mx-auto mb-10 max-w-2xl text-center md:mb-12">
          <h2
            id="stats-02-title"
            className="text-3xl font-bold tracking-tight text-balance md:text-4xl"
          >
            {dictionary.title}
          </h2>
          <p className="mt-4 text-base text-pretty text-muted-foreground md:text-lg">
            {dictionary.description}
          </p>
        </div>

        <dl className="grid gap-8 rounded-2xl border bg-muted/40 p-8 sm:grid-cols-2 md:grid-cols-3 md:p-12">
          {dictionary.items.map((item) => (
            <div key={item.label} className="flex flex-col-reverse text-center">
              <dt className="mt-2 text-sm text-muted-foreground">
                {item.label}
              </dt>
              <dd className="text-4xl font-bold tracking-tight tabular-nums md:text-5xl">
                {item.value}
              </dd>
            </div>
          ))}
        </dl>
      </div>
    </section>
  )
}

import { type StatsDictionary } from "@/registry/bases/base/blocks/stats-02/components/stats-02"

export const dictionary: Record<"en" | "ar", StatsDictionary> = {
  en: {
    title: "Built for teams that move fast",
    description:
      "Thousands of teams rely on Acme every day to ship faster, stay aligned, and keep their customers happy.",
    items: [
      { value: "10,000+", label: "Teams onboarded" },
      { value: "99.9%", label: "Uptime over the last 12 months" },
      { value: "4.9/5", label: "Average customer rating" },
    ],
  },
  ar: {
    title: "صُمّم للفرق التي تتحرك بسرعة",
    description:
      "تعتمد آلاف الفرق على أكمي يوميًا لتسليم أعمالها أسرع، والبقاء على تنسيق دائم، وإسعاد عملائها.",
    items: [
      { value: "10,000+", label: "فرق انضمت إلى المنصة" },
      { value: "99.9%", label: "نسبة التشغيل خلال آخر 12 شهرًا" },
      { value: "4.9/5", label: "متوسط تقييم العملاء" },
    ],
  },
}
